insert into public.products (product_code, product_name, description, current_price, sales_tax_code, quickbooks_tax_code, package_size, product_type)
select imported.product_code, imported.product_name, imported.description, imported.current_price, imported.sales_tax_code, imported.quickbooks_tax_code, imported.package_size, 'LUBE'
from imported_products as imported
where not exists (
  select 1
  from public.products as existing
  where existing.product_code = imported.product_code
);
